/** One quiz question. `right` goes into slot `slot` (0 to 3) among the three wrong choices, so the position of the correct answer is chosen on purpose, lesson by lesson. */
function q(day: number, n: number, prompt: string, right: string, wrong: [string, string, string], slot: 0 | 1 | 2 | 3, explanation: string, audience?: Audience): QuizQuestion {
  const choices: string[] = [...wrong];
  choices.splice(slot, 0, right);
  return { id: `building-ai-agents-${day}-q${n}`, ...(audience ? { audience } : {}), prompt, choices, answer: slot, explanation };
}

